arguments.command:
node -e '
import("./src/slug.js").then(({slugify}) => {
  const cases = [
    ["Hello, World!", undefined, "hello-world"],
    ["Café Déjà Vu", undefined, "cafe-deja-vu"],
    ["東京 Station", undefined, "東京-station"],
    ["alpha beta gamma", {maxLength:12}, "alpha-beta"],
    ["abcdefghij", {maxLength:5}, "abcde"],
    ["  ", undefined, ""],
    ["!!!", undefined, ""],
    ["a b c", {separator:"__"}, "a__b__c"],
    ["alpha beta", {maxLength:12, separator:"__"}, "alpha__beta"],
    ["alpha beta", {maxLength:8, separator:"__"}, "alpha"],
    ["alpha beta", {maxLength:6, separator:"__"}, "alpha_"],
    ["alpha beta", {maxLength:9}, "alpha"],
    ["alpha beta", {maxLength:10}, "alpha-beta"],
    ["alpha beta", {maxLength:100}, "alpha-beta"],
    ["---abc---", undefined, "abc"],
    [null, undefined, "null"],
    ["ábc", {separator:" "}, "abc"],
    ["x", {maxLength:1}, "x"],
    ["a b", {maxLength:1}, "a"],
    ["a", {maxLength:1, separator:"--"}, "a"],
  ];
  for (const [inp, opt, exp] of cases) {
    const got = slugify(inp, opt);
    if (got !== exp) { console.error("FAIL", JSON.stringify(inp), opt, "=>", JSON.stringify(got), "expected", JSON.stringify(exp)); process.exit(1); }
  }
  for (const bad of [{separator:""},{separator:null},{separator:5},{separator:false},{maxLength:0},{maxLength:-1},{maxLength:1.5},{maxLength:"3"},{maxLength:null},{maxLength:NaN}]) {
    try { slugify("abc", bad); console.error("FAIL no throw", bad); process.exit(1); }
    catch (e) { if (!(e instanceof TypeError)) { console.error("FAIL wrong error", bad); process.exit(1); } }
  }
  console.log("ad-hoc spec checks OK");
});
' && npm test 2>&1 | tail -8

