export function slugify(input, options = {}) {
  const separator = options.separator ?? "-";
  if (typeof separator !== "string" || separator.length === 0) {
    throw new TypeError("options.separator must be a non-empty string");
  }

  const maxLength = options.maxLength;
  const hasMaxLength = maxLength !== undefined;
  if (hasMaxLength && (!Number.isInteger(maxLength) || maxLength <= 0)) {
    throw new TypeError("options.maxLength must be a positive integer");
  }

  const words = String(input)
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);

  let slug = words.join(separator);

  if (hasMaxLength && slug.length > maxLength) {
    slug = slug.slice(0, maxLength);
    const boundary = slug.lastIndexOf(separator);
    if (boundary > 0) {
      slug = slug.slice(0, boundary);
    }
    if (slug.endsWith(separator)) {
      slug = slug.slice(0, -separator.length);
    }
  }

  return slug;
}

